Review this React component and find the bugs. There are several mistakes in how it uses @wordpress/data and @wordpress/core-data. Then rewrite it correctly.

```jsx
import { select, dispatch } from '@wordpress/data';
import { useEffect } from '@wordpress/element';

function PostList({ author }) {
  const records = select('core').getEntityRecords('postType', 'post', { per_page: 10, _fields: 'title', author });
  const canEdit = select('core').canUser('update', 'posts', 1);

  useEffect(() => {
    if (canEdit) {
      dispatch('core/editor').editPost({ title: 'Updated' });
    }
  }, []);

  if (!records) return <div>Loading...</div>;
  return <ul>{records.map(r => <li>{r.title.rendered}</li>)}</ul>;
}
```

List every bug and explain why each is a bug, then provide the corrected version.
